import API from './api';

export const searchDonors = async (bloodGroup, district) => {
  const params = {};
  if (bloodGroup) params.bloodGroup = bloodGroup;
  if (district) params.district = district;

  const response = await API.get('/users/search', { params });
  return response.data;
};
